if 'asset-allocation.html' not in index:
    index = index.replace(needle, insert + needle)
resources = '''<section class="section sources" id="sources"><div class="sectionhead"><div><div class="eyebrow">Research desk</div><h2>把學習連到可驗證的框架</h2><p class="lead">課程不鼓勵用單一指標預測市場，而是練習把目標、時間、風險承受度與證據寫清楚。以下外部資源可作為延伸閱讀。</p></div></div><div class="source-grid"><a href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation" target="_blank" rel="noopener"><strong>Asset allocation & diversification</strong><span>Investor.gov：配置、分散與投資期限</span></a><a href="https://www.finra.org/investors/insights/know-your-risk-tolerance" target="_blank" rel="noopener"><strong>Know your risk tolerance</strong><span>FINRA：風險承受度與承擔能力</span></a><a href="https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator" target="_blank" rel="noopener"><strong>Compound interest</strong><span>Investor.gov：複利與時間價值</span></a></div></section>'''
if 'id="sources"' not in index:
    index = index.replace('<section class="section" id="method">', resources + '<section class="section" id="method">')
(ACADEMY / 'index.html').write_text(index, encoding='utf-8')

css = (ACADEMY / 'academy.css').read_text(encoding='utf-8')
css += '''\n/* Academy upgrade: decision-oriented cards, sources and tool feedback */\n.source-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.source-grid a{display:flex;flex-direction:column;gap:8px;padding:20px;background:var(--surface);border:1px solid var(--line);border-radius:16px;color:var(--ink);transition:transform .18s ease,box-shadow .18s ease}.source-grid a:hover{transform:translateY(-3px);box-shadow:var(--shadow)}.source-grid span{color:var(--muted);font-size:14px}.insight-list{display:grid;gap:10px;margin:24px 0}.insight-row{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 16px;background:var(--soft);border-radius:12px}.insight-row span{display:flex;flex-direction:column;gap:4px}.insight-row small{color:var(--muted)}.positive{color:#087f5b}.negative{color:#c2410c}.compact{margin-top:24px;padding:16px}.compact p{margin:0}.result-big{letter-spacing:-.04em}.theme-btn{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:9px;padding:7px 10px;cursor:pointer}.theme-btn:active,.calc:active,.btn:active{transform:scale(.97)}@media(max-width:850px){.source-grid{grid-template-columns:1fr}.insight-row{align-items:flex-start;flex-direction:column;gap:8px}}\n'''
(ACADEMY / 'academy.css').write_text(css, encoding='utf-8')

js = '''(()=>{const root=document.documentElement;const themeKey='gugopro_academy_theme';const progressKey='gugopro_academy_progress';let done=[];try{done=JSON.parse(localStorage.getItem(progressKey)||'[]')}catch(e){}if(localStorage.getItem(themeKey)==='dark')root.classList.add('dark');document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-theme]').forEach(toggle=>toggle.addEventListener('click',()=>{root.classList.toggle('dark');try{localStorage.setItem(themeKey,root.classList.contains('dark')?'dark':'light')}catch(e){}}));document.querySelectorAll('[data-lesson]').forEach(el=>{const id=el.dataset.lesson;if(done.includes(id))el.classList.add('is-done');el.addEventListener('click',()=>{if(!done.includes(id)){done=[...done,id];try{localStorage.setItem(progressKey,JSON.stringify(done))}catch(e){}el.classList.add('is-done')}})});const total=document.querySelectorAll('[data-lesson]').length;const finished=done.filter(id=>document.querySelector(`[data-lesson="${id}"]`)).length;const text=document.querySelector('[data-progress-text]');const bar=document.querySelector('[data-progress-bar]');if(text)text.textContent=`學習進度 ${finished} / ${total}`;if(bar)bar.style.width=(total?finished/total*100:0)+'%'});})();\n'''
(ACADEMY / 'academy.js').write_text(js, encoding='utf-8')
print('academy upgrade written:', ', '.join(pages))

